   File.WriteAllText(Path.Combine(folder,"verification.txt"),report);Debug.Log("PINPOP CRISP REVIEW COMPLETE: failures="+failures);Application.Quit(failures==0?0:1);
  }
  [Serializable]class CopyReport {public string language;public string[] unmapped;}
  void CloseWithCross(string name){Canvas.ForceUpdateCanvases();var button=GameObject.Find(name);var rect=button.GetComponent<RectTransform>();var pointer=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,rect.TransformPoint(rect.rect.center)),button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(pointer,hits);var target=hits.Count==0?null:UnityEngine.EventSystems.ExecuteEvents.GetEventHandler<UnityEngine.EventSystems.IPointerClickHandler>(hits[0].gameObject);Check(target==button,"Pointer reaches close cross: "+name);if(target==button)UnityEngine.EventSystems.ExecuteEvents.Execute(target,pointer,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);}
  Rect ScreenRect(RectTransform rect){var corners=new Vector3[4];rect.GetWorldCorners(corners);Vector2 low=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,corners[0]),high=RectTransformUtility.WorldToScreenPoint(game.Hud.UICamera,corners[2]);return Rect.MinMaxRect(low.x,low.y,high.x,high.y);}
  void EnableVirtualScreen(Vector2Int size){if(virtualScreen!=null){if(virtualScreen.width==size.x&&virtualScreen.height==size.y)return;game.Camera.targetTexture=null;game.Hud.UICamera.targetTexture=null;virtualScreen.Release();Destroy(virtualScreen);}CrispUI.ReviewSize=size;CrispUI.ReviewSafeArea=size.x==1014?new Rect(0,0,size.x,size.y):new Rect(0,102,size.x,size.y-243);virtualScreen=new RenderTexture(size.x,size.y,24);virtualScreen.Create();game.Camera.targetTexture=virtualScreen;game.Hud.UICamera.targetTexture=virtualScreen;}
  void Capture(string name){Canvas.ForceUpdateCanvases();if(!GameLocalization.Turkish){bool clean=true;foreach(var label in FindObjectsByType<Text>(FindObjectsSortMode.None))foreach(char c in GameLocalization.IsNativeLanguageName(label.text)?"":label.text)clean&="çğıöşüÇĞİÖŞÜ".IndexOf(c)<0;Check(clean,"English screen has no untranslated Turkish copy: "+name);}int w=CrispUI.Width,h=CrispUI.Height;var rt=new RenderTexture(w,h,24);var prior=RenderTexture.active;game.Camera.targetTexture=rt;game.Camera.Render();game.Hud.UICamera.targetTexture=rt;game.Hud.UICamera.Render();RenderTexture.active=rt;var image=new Texture2D(w,h,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,w,h),0,0);image.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),image.EncodeToPNG());if(name.StartsWith("helper-")){foreach(var t in FindObjectsByType<Text>(FindObjectsSortMode.None))if(t.text=="YETERSİZ")Debug.Log("Unexpected active stock label: "+t.name+" parent="+t.transform.parent.name);}game.Camera.targetTexture=virtualScreen;game.Hud.UICamera.targetTexture=virtualScreen;RenderTexture.active=prior;rt.Release();Destroy(rt);Destroy(image);}
 }
 internal static class AimVisualAudit {
  public static bool Verify(PinPopGame game,out string details){
   var ring=game.PowerRing.transform;var camera=game.Camera;Vector2 center=camera.WorldToScreenPoint(ring.position);float min=float.MaxValue,max=float.MinValue;
   var track=ring.Find("Power ring track");foreach(var vertex in track.GetComponent<MeshFilter>().sharedMesh.vertices){float x=camera.WorldToScreenPoint(track.TransformPoint(vertex)).x;min=Mathf.Min(min,x);max=Mathf.Max(max,x);}
   float expected=2*Vector2.Distance(center,camera.WorldToScreenPoint(ring.position+camera.transform.right*BowlingBall.Radius));int inside=0;
   foreach(var renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None)){if(!renderer.name.StartsWith("Table aim dot "))continue;Vector2 point=camera.WorldToScreenPoint(renderer.transform.position);float radius=Vector2.Distance(point,camera.WorldToScreenPoint(renderer.transform.position+camera.transform.right*renderer.bounds.extents.x));if(Vector2.Distance(point,center)<(max-min)*.5f+radius)inside++;}
   details="Aim ring diameter="+(max-min).ToString("F2")+"px, ball at target="+expected.ToString("F2")+"px, overlapping dots="+inside;
   return Mathf.Abs(max-min-expected)<1&&inside==0&&ring.gameObject.activeInHierarchy;
  }
 }
